'use strict';
const test=require('node:test'),assert=require('node:assert/strict');
const {Decoder,frame,inspectBootstrap}=require('../../../collectors/nodered/live-integration/private-launch-proxy');
const bootstrap=require('../../../collectors/nodered/live-integration/private-bootstrap');
function descriptor(){const d={batch_bytes:512,batch_events:1,ca_sha256:'66'.repeat(32),epoch:'1',export_credential:'00000000-0000-4000-8000-000000000001',export_leaf:'11'.repeat(32),generation:'22'.repeat(32),identity:'00'.repeat(32),launch_slot:'88'.repeat(32),launcher_sha256:'99'.repeat(32),manifest_sha256:'33'.repeat(32),marker_public:'44'.repeat(32),nonce:'00000000-0000-4000-8000-000000000002',product_credential:'00000000-0000-4000-8000-000000000003',product_leaf:'55'.repeat(32),profile_id:'00000000-0000-4000-8000-000000000503',queue_bytes:1024,queue_ttl_ms:60000,runtime:'00000000-0000-4000-8000-000000000004',server_leaf:'77'.repeat(32),tenant:'00000000-0000-4000-8000-000000000005',version:1};d.identity=bootstrap.commitment(d);return d;}
function clb(d=descriptor()){const b=Buffer.from(JSON.stringify(d)),h=Buffer.alloc(8);h.write('CLB1');h.writeUInt32BE(b.length,4);return Buffer.concat([h,b,Buffer.alloc(32,7)]);}
test('CBP1 decoder accepts arbitrary segmentation without retaining payload',()=>{const encoded=frame(73,Buffer.alloc(32,5)),seen=[];let failed=0;const decoder=new Decoder((type,data)=>seen.push([type,Buffer.from(data)]),()=>failed++);for(const byte of encoded)decoder.push(Buffer.from([byte]));decoder.end();assert.equal(failed,0);assert.equal(seen.length,1);assert.equal(seen[0][0],73);assert.deepEqual(seen[0][1],Buffer.alloc(32,5));assert.equal(decoder.pending.length,0);});
test('truncated, malformed, high-bit magic and oversized frames fail',()=>{for(const input of [frame(73,Buffer.alloc(32)).subarray(0,12),Buffer.from('CBP2I0000'),Buffer.from([0xc3,0xc2,0xd0,0xb1,73,0,0,0,0]),Buffer.from([67,66,80,49,73,0,0,0xff,0xff])]){let failed=0;const decoder=new Decoder(()=>assert.fail('accepted'),()=>failed++);decoder.push(input);decoder.end();assert.equal(failed,1);}});
test('bootstrap framing checks exact length, commitment and bounded metadata',()=>{const d=descriptor(),b=clb(d);assert.equal(inspectBootstrap(b).identity,d.identity);assert.throws(()=>inspectBootstrap(b.subarray(0,b.length-1)));assert.throws(()=>inspectBootstrap(Buffer.concat([b,Buffer.from([0])])));const bad=Buffer.from(b);bad[0]=0xc3;assert.throws(()=>inspectBootstrap(bad));const altered={...d,launch_slot:'aa'.repeat(32)};assert.throws(()=>inspectBootstrap(clb(altered)));});
function harness(){
 const vm=require('node:vm'),fs=require('node:fs'),path=require('node:path'),{EventEmitter}=require('node:events');
 const code=fs.readFileSync(path.resolve(__dirname,'../../../collectors/nodered/live-integration/private-launch-proxy.js'),'utf8');
 class Stream extends EventEmitter{constructor(){super();this.destroyed=false;this.writes=[];}write(v,cb){this.writes.push(Buffer.from(v));if(cb){if(this.defer)this.pendingWrite=cb;else cb();}return !this.backpressure;}end(v,cb){if(Buffer.isBuffer(v))this.writes.push(Buffer.from(v));if(cb)cb();}pause(){}resume(){}destroy(){if(!this.destroyed){this.destroyed=true;this.emit('close');}}}
 const input=new Stream(),output=new Stream(),child=new EventEmitter(),timers=[];child.pid=33;child.stdio=[null,null,null,new Stream(),new Stream(),new Stream()];let spawned=0;
 const proc={stdin:input,stdout:output,stderr:new Stream(),execPath:'/usr/local/bin/node',argv:['/usr/local/bin/node','/adapter/live-integration/private-launch-proxy.js'],execArgv:[],pid:22,env:{FLOWS:'',HOME:'',HOSTNAME:'',LANG:'',NODE_PATH:'',NODE_RED_VERSION:'',NODE_VERSION:'',PATH:'',TZ:'',YARN_VERSION:''},exitCode:0};
 const fakeFs={readFileSync:p=>{const pid=p.includes('/33/')?'33':'22';return pid+' (synthetic) '+['S',...Array(18).fill('0'),'123'].join(' ');}};
 const mod={exports:{}};function req(name){if(name==='node:fs')return fakeFs;if(name==='node:child_process')return {spawn:(binary,args,opts)=>{assert.equal(binary,'/usr/local/bin/node');assert.deepEqual(Array.from(args),['/adapter/live-integration/live-main.js']);assert.deepEqual(Array.from(opts.stdio),['ignore','ignore','ignore','pipe','pipe','pipe']);spawned++;return child;}};if(name==='./private-bootstrap')return bootstrap;throw Error('unexpected module');}req.main=mod;
 vm.runInNewContext(code,{require:req,module:mod,Buffer,process:proc,setTimeout:(fn,ms)=>{const t={fn,ms,cleared:false};timers.push(t);return t;},clearTimeout:t=>{if(t)t.cleared=true;}},{filename:'private-launch-proxy.js'});
 return {input,output,child,proc,timers,spawned:()=>spawned};
}
test('one-shot proxy correlates ready, exact relay and preserves child after attach loss',()=>{
 const h=harness(),d=descriptor();h.input.emit('data',frame(73,Buffer.alloc(32,5)));assert.equal(h.output.writes[0][4],72);
 h.input.emit('data',frame(66,clb(d)));assert.equal(h.spawned(),1);assert.equal(h.output.writes[1][4],83);assert.deepEqual(h.child.stdio[3].writes[0],clb(d));
 const q=Buffer.alloc(108);q.write('CQP1');Buffer.from(d.generation,'hex').copy(q,4);Buffer.from(d.identity,'hex').copy(q,36);q.writeBigUInt64BE(1n,68);q.fill(5,76);h.child.stdio[4].emit('data',q);assert.equal(h.output.writes[2][4],81);
 const reply=Buffer.alloc(120);reply.write('CRP1');q.copy(reply,4,4);reply.writeBigUInt64BE(1n,108);reply.writeUInt32BE(500,116);h.input.emit('data',frame(82,reply));assert.deepEqual(h.child.stdio[4].writes[0],reply);
 const ready=Buffer.alloc(76);ready.write('CLR1');Buffer.from(d.generation,'hex').copy(ready,4);Buffer.from(d.identity,'hex').copy(ready,36);ready.writeBigUInt64BE(1n,68);h.child.stdio[5].emit('data',ready);h.child.stdio[5].emit('end');assert.equal(h.output.writes[3][4],89);
 h.input.emit('end');assert.equal(h.child.stdio[4].destroyed,true);assert.equal(h.spawned(),1);assert.equal(h.proc.exitCode,0);assert.equal(typeof h.child.kill,'undefined');
});
test('duplicate bootstrap closes capture with no relaunch',()=>{const h=harness(),d=descriptor();h.input.emit('data',frame(73,Buffer.alloc(32,5)));h.input.emit('data',frame(66,clb(d)));h.input.emit('data',frame(66,clb(d)));assert.equal(h.spawned(),1);assert.equal(h.child.stdio[4].destroyed,true);assert.equal(h.proc.exitCode,0);});

test('mismatched permit response closes capture without killing the child',()=>{const h=harness(),d=descriptor();h.input.emit('data',frame(73,Buffer.alloc(32,5)));h.input.emit('data',frame(66,clb(d)));const q=Buffer.alloc(108);q.write('CQP1');Buffer.from(d.generation,'hex').copy(q,4);Buffer.from(d.identity,'hex').copy(q,36);q.writeBigUInt64BE(1n,68);q.fill(5,76);h.child.stdio[4].emit('data',q);const bad=Buffer.alloc(120);bad.write('CRP1');h.input.emit('data',frame(82,bad));assert(h.child.stdio[4].destroyed);assert.equal(h.spawned(),1);assert.equal(h.proc.exitCode,0);});
test('trailing or malformed readiness never yields Y and closes capture',()=>{for(const bad of [Buffer.alloc(77),Buffer.alloc(76)]){const h=harness(),d=descriptor();h.input.emit('data',frame(73,Buffer.alloc(32,5)));h.input.emit('data',frame(66,clb(d)));h.child.stdio[5].emit('data',bad);h.child.stdio[5].emit('end');assert(!h.output.writes.some(x=>x[4]===89));assert(h.child.stdio[4].destroyed);assert.equal(h.spawned(),1);}});

test('backpressure after spawn closes capture and leaves the child',()=>{const h=harness(),d=descriptor();h.input.emit('data',frame(73,Buffer.alloc(32,5)));h.input.emit('data',frame(66,clb(d)));h.output.backpressure=true;const q=Buffer.alloc(108);q.write('CQP1');Buffer.from(d.generation,'hex').copy(q,4);Buffer.from(d.identity,'hex').copy(q,36);q.writeBigUInt64BE(1n,68);q.fill(5,76);h.child.stdio[4].emit('data',q);assert(h.child.stdio[4].destroyed);assert.equal(h.spawned(),1);assert.equal(h.proc.exitCode,0);});
test('late status read error cannot become a readiness receipt',()=>{const h=harness(),d=descriptor();h.input.emit('data',frame(73,Buffer.alloc(32,5)));h.input.emit('data',frame(66,clb(d)));const ready=Buffer.alloc(76);ready.write('CLR1');Buffer.from(d.generation,'hex').copy(ready,4);Buffer.from(d.identity,'hex').copy(ready,36);ready.writeBigUInt64BE(1n,68);const status=h.child.stdio[5];status.destroy=()=>{};status.emit('data',ready);status.emit('end');status.emit('error',Error('controlled'));status.emit('close');assert(!h.output.writes.some(x=>x[4]===89));assert(h.child.stdio[4].destroyed);});
test('ready waits for an outstanding refresh response before forwarding',()=>{const h=harness(),d=descriptor();h.input.emit('data',frame(73,Buffer.alloc(32,5)));h.input.emit('data',frame(66,clb(d)));const q=Buffer.alloc(108);q.write('CQP1');Buffer.from(d.generation,'hex').copy(q,4);Buffer.from(d.identity,'hex').copy(q,36);q.writeBigUInt64BE(1n,68);q.fill(5,76);h.child.stdio[4].emit('data',q);const ready=Buffer.alloc(76);ready.write('CLR1');Buffer.from(d.generation,'hex').copy(ready,4);Buffer.from(d.identity,'hex').copy(ready,36);ready.writeBigUInt64BE(1n,68);h.child.stdio[5].emit('data',ready);h.child.stdio[5].emit('end');assert.deepEqual(h.output.writes.map(x=>x[4]),[72,83,81]);const reply=Buffer.alloc(120);reply.write('CRP1');q.copy(reply,4,4);reply.writeBigUInt64BE(1n,108);reply.writeUInt32BE(500,116);h.input.emit('data',frame(82,reply));assert.deepEqual(h.output.writes.map(x=>x[4]),[72,83,81,89]);});
test('ready waits for a fragmented request and its response',()=>{const h=harness(),d=descriptor();h.input.emit('data',frame(73,Buffer.alloc(32,5)));h.input.emit('data',frame(66,clb(d)));const q=Buffer.alloc(108);q.write('CQP1');Buffer.from(d.generation,'hex').copy(q,4);Buffer.from(d.identity,'hex').copy(q,36);q.writeBigUInt64BE(1n,68);q.fill(5,76);h.child.stdio[4].emit('data',q.subarray(0,20));const ready=Buffer.alloc(76);ready.write('CLR1');Buffer.from(d.generation,'hex').copy(ready,4);Buffer.from(d.identity,'hex').copy(ready,36);ready.writeBigUInt64BE(1n,68);h.child.stdio[5].emit('data',ready);h.child.stdio[5].emit('end');assert.deepEqual(h.output.writes.map(x=>x[4]),[72,83]);h.child.stdio[4].emit('data',q.subarray(20));assert.deepEqual(h.output.writes.map(x=>x[4]),[72,83,81]);const reply=Buffer.alloc(120);reply.write('CRP1');q.copy(reply,4,4);reply.writeBigUInt64BE(1n,108);reply.writeUInt32BE(500,116);h.input.emit('data',frame(82,reply));assert.deepEqual(h.output.writes.map(x=>x[4]),[72,83,81,89]);});

test('duplicate response while the first child write is pending fails closed',()=>{const h=harness(),d=descriptor();h.input.emit('data',frame(73,Buffer.alloc(32,5)));h.input.emit('data',frame(66,clb(d)));const q=Buffer.alloc(108);q.write('CQP1');Buffer.from(d.generation,'hex').copy(q,4);Buffer.from(d.identity,'hex').copy(q,36);q.writeBigUInt64BE(1n,68);q.fill(5,76);h.child.stdio[4].emit('data',q);const reply=Buffer.alloc(120);reply.write('CRP1');q.copy(reply,4,4);reply.writeBigUInt64BE(1n,108);reply.writeUInt32BE(500,116);h.child.stdio[4].defer=true;h.input.emit('data',frame(82,reply));assert.equal(h.child.stdio[4].writes.length,1);assert(!h.timers.find(t=>t.ms===2000).cleared);h.input.emit('data',frame(82,reply));assert(h.child.stdio[4].destroyed);assert.equal(h.child.stdio[4].writes.length,1);assert.equal(h.spawned(),1);});
test('response write callback remains deadline bounded',()=>{const h=harness(),d=descriptor();h.input.emit('data',frame(73,Buffer.alloc(32,5)));h.input.emit('data',frame(66,clb(d)));const q=Buffer.alloc(108);q.write('CQP1');Buffer.from(d.generation,'hex').copy(q,4);Buffer.from(d.identity,'hex').copy(q,36);q.writeBigUInt64BE(1n,68);q.fill(5,76);h.child.stdio[4].emit('data',q);const reply=Buffer.alloc(120);reply.write('CRP1');q.copy(reply,4,4);reply.writeBigUInt64BE(1n,108);reply.writeUInt32BE(500,116);h.child.stdio[4].defer=true;h.input.emit('data',frame(82,reply));h.timers.find(t=>t.ms===2000&&!t.cleared).fn();assert(h.child.stdio[4].destroyed);assert.equal(h.spawned(),1);});
